<script setup lang="ts">
import { computed, inject } from 'vue'
import type { ChartData, ChartOptions } from 'chart.js'
import { Bar, Doughnut, Line } from 'vue-chartjs'
import { CHART_COLORS, setupChartTheme } from '@/dashboard/config/chartTheme'
import { colorForStatus, toneForStatus } from '@/dashboard/constants/status'
import { useProjectSummary } from '@/dashboard/composables/useProjectSummary'
import { FED_SEARCH_KEY, PROJECT_MILESTONES_KEY } from '@/dashboard/injectionKeys'
import type { MetricItem, Tone } from '@/dashboard/types/project'
import MetricStrip from './common/MetricStrip.vue'
import PanelCard from './common/PanelCard.vue'

setupChartTheme()

const { loading: fedLoading, error: fedError, progress: fedProgress } = inject(FED_SEARCH_KEY)!

const {
  projects,
  loading: milestonesLoading,
  loadedCount,
  totalCount,
} = inject(PROJECT_MILESTONES_KEY)!

const { hasData, summary: dashboard } = useProjectSummary(projects)

interface RawMetric {
  value: string
  subtitle: string
}

function toMetric(label: string, metric: RawMetric, tone?: Tone): MetricItem {
  return { label, value: metric.value, note: metric.subtitle, tone }
}

const metricItems = computed<MetricItem[]>(() => [
  toMetric('Total Projects', dashboard.value.metrics.totalProjects),
  toMetric('On Track', dashboard.value.metrics.onTrack, 'ok'),
  toMetric('Potential Delay', dashboard.value.metrics.potentialDelay, 'warn'),
  toMetric('Delayed', dashboard.value.metrics.delayed, 'bad'),
  toMetric('Late Projects', dashboard.value.metrics.lateProjects),
  toMetric('Avg Progress', dashboard.value.metrics.avgProgress),
])

const totalProjects = computed(() =>
  dashboard.value.statusMix.reduce((sum, item) => sum + item.value, 0),
)

const statusMixSummary = computed(() =>
  dashboard.value.statusMix.map((item) => `${item.label} ${item.value}`).join(', '),
)

const donutData = computed<ChartData<'doughnut'>>(() => ({
  labels: dashboard.value.statusMix.map((item) => item.label),
  datasets: [
    {
      data: dashboard.value.statusMix.map((item) => item.value),
      backgroundColor: dashboard.value.statusMix.map((item) => colorForStatus(item.label, item.color)),
      borderColor: CHART_COLORS.surface,
      borderWidth: 3,
      hoverOffset: 4,
    },
  ],
}))

const donutOptions: ChartOptions<'doughnut'> = {
  responsive: true,
  maintainAspectRatio: false,
  cutout: '72%',
  plugins: {
    legend: { display: false },
  },
}

const barSummary = computed(() =>
  dashboard.value.massProduction.map((item) => `${item.month}: ${item.value}`).join(', '),
)

const barData = computed<ChartData<'bar'>>(() => ({
  labels: dashboard.value.massProduction.map((item) => item.month),
  datasets: [
    {
      label: 'Mass Production',
      data: dashboard.value.massProduction.map((item) => item.value),
      backgroundColor: CHART_COLORS.primary,
      borderRadius: 2,
      barPercentage: 0.55,
    },
  ],
}))

const barOptions: ChartOptions<'bar'> = {
  responsive: true,
  maintainAspectRatio: false,
  plugins: {
    legend: { display: false },
  },
  scales: {
    y: {
      beginAtZero: true,
      grid: { color: CHART_COLORS.grid },
      ticks: { stepSize: 1, color: CHART_COLORS.tick },
      border: { display: false },
    },
    x: {
      grid: { display: false },
      ticks: { color: CHART_COLORS.tick },
      border: { color: CHART_COLORS.grid },
    },
  },
}

const lineData = computed<ChartData<'line'>>(() => ({
  labels: dashboard.value.burnDown.labels,
  datasets: [
    {
      label: 'Planned',
      data: dashboard.value.burnDown.planned,
      borderColor: CHART_COLORS.muted,
      backgroundColor: CHART_COLORS.muted,
      borderDash: [6, 4],
      borderWidth: 2,
      pointRadius: 2,
      tension: 0,
    },
    {
      label: 'Actual',
      data: dashboard.value.burnDown.actual,
      borderColor: CHART_COLORS.primary,
      backgroundColor: CHART_COLORS.primary,
      borderWidth: 2.5,
      pointRadius: 3.5,
      tension: 0,
    },
  ],
}))

const lineOptions: ChartOptions<'line'> = {
  responsive: true,
  maintainAspectRatio: false,
  interaction: { mode: 'index', intersect: false },
  plugins: {
    legend: {
      position: 'bottom',
      align: 'start',
      labels: { usePointStyle: true, boxWidth: 8, boxHeight: 8, padding: 16 },
    },
  },
  scales: {
    y: {
      grid: { color: CHART_COLORS.grid },
      ticks: { color: CHART_COLORS.tick, maxTicksLimit: 5 },
      border: { display: false },
    },
    x: {
      grid: { display: false },
      ticks: { color: CHART_COLORS.tick },
      border: { color: CHART_COLORS.grid },
    },
  },
}

const taskSegments = computed(() =>
  dashboard.value.topLevelTasks.map((task) => ({
    ...task,
    color: colorForStatus(task.label, task.color),
    tone: toneForStatus(task.label),
  })),
)

/** Bar segments with a count (empty statuses stay in the legend only). */
const barSegments = computed(() => taskSegments.value.filter((task) => task.value > 0))
</script>

<template>
  <div class="projects-tab tab-enter">
    <div v-if="fedLoading" class="fed-banner fed-loading" role="status" aria-live="polite">
      <i class="mdi mdi-loading mdi-spin" aria-hidden="true"></i>
      Fetching live Project Spaces from 3DExperience…
      <span v-if="fedProgress > 0" class="fed-progress-text">{{ fedProgress }}%</span>
      <span v-if="fedProgress > 0" class="fed-progress-bar-wrap" aria-hidden="true">
        <span class="fed-progress-bar" :style="{ width: fedProgress + '%' }"></span>
      </span>
    </div>
    <div v-else-if="fedError" class="fed-banner fed-error" role="alert">
      <i class="mdi mdi-alert-outline" aria-hidden="true"></i>
      Live data unavailable.
      <span class="fed-error-detail">{{ fedError }}</span>
    </div>
    <div v-else-if="milestonesLoading" class="fed-banner fed-loading" role="status" aria-live="polite">
      <i class="mdi mdi-loading mdi-spin" aria-hidden="true"></i>
      Loading project details… {{ loadedCount }} / {{ totalCount }}
    </div>
    <div v-else-if="!hasData" class="fed-banner fed-error" role="status">
      <i class="mdi mdi-information-outline" aria-hidden="true"></i>
      No matching projects found.
    </div>
    <div v-else class="fed-banner fed-ok" role="status">
      <i class="mdi mdi-check-circle-outline" aria-hidden="true"></i>
      {{ projects.length }} project{{ projects.length !== 1 ? 's' : '' }} loaded from 3DEXPERIENCE.
    </div>

    <template v-if="hasData">
      <MetricStrip :items="metricItems" label="Portfolio summary" />

      <div class="charts-grid">
        <PanelCard title="Project Status Mix">
          <div class="donut-wrapper">
            <div
              class="donut-chart-box"
              role="img"
              :aria-label="`Project status mix: ${statusMixSummary}`"
            >
              <Doughnut :data="donutData" :options="donutOptions" />
              <div class="donut-center-text">
                <span class="donut-total">{{ totalProjects }}</span>
                <span class="donut-caption">Projects</span>
              </div>
            </div>
            <ul class="legend-list">
              <li v-for="item in dashboard.statusMix" :key="item.label" class="legend-item">
                <span
                  class="dot"
                  :style="{ backgroundColor: colorForStatus(item.label, item.color) }"
                ></span>
                <span class="legend-label">{{ item.label }}</span>
                <span class="legend-val">{{ item.value }}</span>
              </li>
            </ul>
          </div>
        </PanelCard>

        <PanelCard title="Mass Production Schedule" subtitle="by MP target">
          <div
            class="chart-box bar-chart-box"
            role="img"
            :aria-label="`Mass production schedule. ${barSummary}`"
          >
            <Bar :data="barData" :options="barOptions" />
          </div>
        </PanelCard>
      </div>

      <div class="charts-grid">
        <PanelCard title="Top Level Tasks">
          <div class="segmented-wrapper">
            <div class="segmented-bar">
              <div
                v-for="task in barSegments"
                :key="task.label"
                :class="['segment', `tone-${task.tone}`]"
                :style="{ backgroundColor: task.color, flex: task.value }"
              >
                {{ task.value }}
              </div>
            </div>
            <ul class="legend-row">
              <li v-for="task in taskSegments" :key="task.label" class="legend-item">
                <span class="dot" :style="{ backgroundColor: task.color }"></span>
                <span class="legend-label">{{ task.label }}</span>
              </li>
            </ul>
          </div>
        </PanelCard>

        <PanelCard title="Burn Down" subtitle="remaining tasks / week">
          <div
            class="chart-box line-chart-box"
            role="img"
            aria-label="Burn down chart: planned versus actual remaining tasks by week"
          >
            <Line :data="lineData" :options="lineOptions" />
          </div>
        </PanelCard>
      </div>
    </template>
  </div>
</template>

