import { computed, type Ref } from 'vue'
import { STATUS_META } from '@/dashboard/constants/status'
import { formatMonthLabel, parseApiDate, shortMonth } from '@/dashboard/utils/date'
import { findMilestone } from '@/dashboard/utils/milestones'
import { classifyTask, isTaskComplete, isTrue } from '@/dashboard/utils/projectStatus'
import type { StatusKey } from '@/dashboard/types/project'
import type { ProjectDetail, ProjectTask } from './useProjectMilestones'

interface SummaryMetric {
  value: string
  subtitle: string
}

interface StatusCount {
  label: string
  value: number
  color: string
}

export interface DashboardSummary {
  metrics: Record<
    'totalProjects' | 'onTrack' | 'potentialDelay' | 'delayed' | 'lateProjects' | 'avgProgress',
    SummaryMetric
  >
  statusMix: StatusCount[]
  massProduction: Array<{ month: string; value: number }>
  topLevelTasks: StatusCount[]
  burnDown: { labels: string[]; planned: number[]; actual: number[] }
}

const STATUS_ORDER: StatusKey[] = ['on-track', 'potential-delay', 'delayed']

/** Max points on the burn-down chart; longer ranges use multi-week steps. */
const MAX_BURN_DOWN_POINTS = 26
const DAY_MS = 24 * 60 * 60 * 1000

function countByStatus(statuses: StatusKey[]) {
  return STATUS_ORDER.map((key) => ({
    label: STATUS_META[key].label as string,
    value: statuses.filter((s) => s === key).length,
    color: STATUS_META[key].color,
  }))
}

// ─── Mass production schedule ────────────────────────────────────────────────

/** The customer MP milestone ("MP CUSTOMER", or plain "MP"); projects without one are skipped. */
function massProductionMilestone(project: ProjectDetail): ProjectTask | undefined {
  return findMilestone(project, 'MP', 'CUSTOMER')
}

function massProduction(projects: ProjectDetail[]) {
  const perMonth = new Map<number, number>()
  for (const project of projects) {
    const milestone = massProductionMilestone(project)
    const date = milestone && parseApiDate(milestone.dueDate ?? milestone.forecastFinishDate)
    if (!date) continue
    const monthStart = new Date(date.getFullYear(), date.getMonth(), 1).getTime()
    perMonth.set(monthStart, (perMonth.get(monthStart) ?? 0) + 1)
  }
  return Array.from(perMonth.entries())
    .sort(([a], [b]) => a - b)
    .map(([monthStart, value]) => ({ month: formatMonthLabel(new Date(monthStart)), value }))
}

// ─── Burn down ───────────────────────────────────────────────────────────────

/** Top-level work items (phases/tasks), excluding milestones and gates. */
function isTopLevelTask(task: ProjectTask): boolean {
  return !isTrue(task.isTypeMilestone) && !isTrue(task.isTypeGate)
}

/** Work tasks only: no phases/summary tasks, milestones or gates. */
function isWorkTask(task: ProjectTask): boolean {
  return !isTrue(task.isSummaryTask) && !isTrue(task.isTypeMilestone) && !isTrue(task.isTypeGate)
}

function burnDown(projects: ProjectDetail[]): DashboardSummary['burnDown'] {
  const tasks = projects.flatMap((p) => p.tasks.filter(isWorkTask))
  const plannedFinish = tasks.map((t) => parseApiDate(t.dueDate))
  const actualFinish = tasks.map(
    (t, i) => parseApiDate(t.actualFinishDate) ?? (isTaskComplete(t) ? plannedFinish[i] : null),
  )

  const starts = tasks.map((t) => parseApiDate(t.estimatedStartDate)).filter((d): d is Date => !!d)
  // Run until the later of the last planned finish and the last actual finish.
  const ends = [...plannedFinish, ...actualFinish].filter((d): d is Date => !!d)
  if (!starts.length || !ends.length) return { labels: [], planned: [], actual: [] }

  const first = new Date(Math.min(...starts.map((d) => d.getTime())))
  const last = Math.max(...ends.map((d) => d.getTime()))
  const weeks = Math.max(1, Math.ceil((last - first.getTime()) / (7 * DAY_MS)))
  const stepDays = 7 * Math.ceil(weeks / MAX_BURN_DOWN_POINTS)
  const now = Date.now()

  const labels: string[] = []
  const planned: number[] = []
  const actual: (number | null)[] = []

  for (let t = first.getTime() + stepDays * DAY_MS; ; t += stepDays * DAY_MS) {
    const point = new Date(Math.min(t, last))
    labels.push(`${point.getDate()} ${shortMonth(point)}`)
    planned.push(plannedFinish.filter((d) => !d || d.getTime() > point.getTime()).length)
    actual.push(
      point.getTime() <= now
        ? actualFinish.filter((d) => !d || d.getTime() > point.getTime()).length
        : null,
    )
    if (t >= last) break
  }

  // Chart.js draws null as a gap: the actual line stops at today.
  return { labels, planned, actual: actual as number[] }
}

// ─── Summary ─────────────────────────────────────────────────────────────────

function buildSummary(projects: ProjectDetail[]): DashboardSummary {
  const total = projects.length
  const statusMix = countByStatus(projects.map((p) => p.statusKey))
  const [onTrack, potentialDelay, delayed] = statusMix.map((s) => s.value)
  const late = potentialDelay + delayed
  const avgProgress = total
    ? projects.reduce((sum, p) => sum + (p.percentComplete ?? 0), 0) / total
    : 0
  const latePercent = total ? Math.round((late / total) * 100) : 0

  return {
    metrics: {
      totalProjects: { value: String(total), subtitle: 'from 3DEXPERIENCE' },
      onTrack: { value: String(onTrack), subtitle: 'no open risk' },
      potentialDelay: { value: String(potentialDelay), subtitle: 'watch list' },
      delayed: { value: String(delayed), subtitle: 'needs escalation' },
      lateProjects: { value: `${latePercent}%`, subtitle: `${late} of ${total}` },
      avgProgress: { value: `${Math.round(avgProgress)}%`, subtitle: 'across portfolio' },
    },
    statusMix,
    massProduction: massProduction(projects),
    // Milestones/gates can sit at the top level too (e.g. "PP0 INDO"); they are not tasks.
    topLevelTasks: countByStatus(
      projects.flatMap((p) => p.phases.filter(isTopLevelTask).map(classifyTask)),
    ),
    burnDown: burnDown(projects),
  }
}

/** Projects-tab data from the loaded projects (all zero/empty until projects are loaded). */
export function useProjectSummary(projects: Ref<ProjectDetail[]>) {
  const hasData = computed(() => projects.value.length > 0)
  const summary = computed<DashboardSummary>(() => buildSummary(projects.value))
  return { hasData, summary }
}
