import { computed, type Ref } from 'vue'
import {
  collectMilestoneEvents,
  findMilestone,
  SIDE_LABELS,
  type MilestoneSide,
} from '@/dashboard/utils/milestones'
import { isTaskComplete } from '@/dashboard/utils/projectStatus'
import type { MetricItem, MetricSplitValue } from '@/dashboard/types/project'
import type { ProjectDetail } from './useProjectMilestones'

const pad2 = (n: number) => String(n).padStart(2, '0')

/** Sides in card order (Customer first, as on the card design). */
const CARD_SIDES: MilestoneSide[] = ['CUSTOMER', 'INDO']

/**
 * Of the projects that have this event's milestone on the given side,
 * how many completed it, e.g. Customer "02/04".
 */
function completionValue(
  projects: ProjectDetail[],
  event: string,
  side: MilestoneSide,
): MetricSplitValue {
  let completed = 0
  let total = 0
  for (const project of projects) {
    const milestone = findMilestone(project, event, side)
    if (!milestone) continue
    total++
    if (isTaskComplete(milestone)) completed++
  }

  const label = SIDE_LABELS[side]
  return total ? { label, value: pad2(completed), of: `/${pad2(total)}` } : { label, value: '-' }
}

/** One metric card per milestone event (PP0, PP1, …), split into Customer and Indo counts. */
export function useMilestoneCompletion(projects: Ref<ProjectDetail[]>) {
  const items = computed<MetricItem[]>(() =>
    collectMilestoneEvents(projects.value).map((event) => ({
      key: `milestone:${event}`,
      label: event,
      split: CARD_SIDES.map((side) => completionValue(projects.value, event, side)),
    })),
  )
  return { items }
}
