import { ref, onMounted } from 'vue'
import Util from '@/utility/util'
import { getPlatform, getTenant } from '@/config/platformUrls'
import { httpRequest } from '@/api/transport'

/**
 * Normalised Project Space item after flattening the API attributes array.
 * Field names match the `name` values from the attributes array in the response.
 */
export interface FedSearchItem {
  /** Internal resource id */
  resourceid?: string
  /** Human-readable project name */
  'ds6w:label'?: string
  /** Short description */
  'ds6w:description'?: string
  /** Identifier (same as label for Project Space) */
  'ds6w:identifier'?: string
  /** Owner login */
  owner?: string
  /** Responsible person display name (from snippet) */
  'ds6w:responsible:snippet'?: string
  /** Responsible uid */
  'ds6w:responsibleUid'?: string
  /** Status e.g. "Project Space.Active" */
  'ds6w:what/ds6w:status'?: string
  /** Created date (from facet) */
  'ds6w:when/ds6w:created'?: string
  /** Modified date (from facet) */
  'ds6w:when/ds6w:modified'?: string
  /** Small icon URL */
  type_icon_url?: string
  /** Preview / thumbnail URL */
  preview_url?: string
  /** Allow any other attribute by name */
  [key: string]: unknown
}

interface RawAttribute {
  name: string
  value?: unknown
  text?: Array<{ content?: string }>
}

/** Results requested per page (matches the confirmed-working reference script). */
const PAGE_SIZE = 100

/** Top-level fields that live directly on the result object (not inside attributes[]). */
const TOP_LEVEL_FIELDS = ['resourceid', 'physicalid', 'dataelementid', 'type', 'source'] as const

/** Tenant used when the widget runs outside 3DDashboard (no platform id available). */
const FALLBACK_TENANT = 'OnPremise'

/**
 * Search endpoint, relative to the 3DSearch service URL resolved at runtime.
 * The query parameter matches what 3DDashboard itself sends (CSRF protection).
 */
const SEARCH_PATH = '/search?xrequestedwith=xmlhttprequest'

/** Federated search lives under "/federated"; some platforms return the 3DSearch URL without it. */
function searchEndpoint(searchUrl: string): string {
  const base = searchUrl.toLowerCase().endsWith('/federated') ? searchUrl : `${searchUrl}/federated`
  return `${base}${SEARCH_PATH}`
}

const SEARCH_HEADERS = { 'x-requested-with': 'XMLHttpRequest, csrf protection' }

/**
 * Base search payload. Paging fields (`start` / `next_start`) are added per request
 * in fetchProjectSpaces().
 */
function buildPayload(securityContext: string) {
  return {
    with_indexing_date: true,
    with_synthesis: true,
    with_nls: false,
    label: '3DSearch-admin_platform-TopBarSearch-1791953643425',
    locale: 'en',
    select_predicate: [
      'ds6w:label',
      'ds6w:type',
      'ds6w:description',
      'ds6w:identifier',
      'ds6w:modified',
      'ds6w:created',
      'ds6wg:revision',
      'ds6w:status',
      'ds6w:responsible',
      'owner',
      'ds6w:responsibleUid',
      'ds6wg:filesize',
      'ds6w:project',
      'ds6w:dataSource',
      'ds6w:community',
      'ds6w:originator',
      'dsgeo:referential',
      'ds6w:lastModifiedBy',
      'ds6w:repository',
      'dcterms:title',
      'dcterms:description',
    ],
    with_synthesis_hierarchical: true,
    select_file: ['icon', 'thumbnail_2d'],
    query: '(3dexpps:#all)',
    refine: {},
    select_exclude_synthesis: ['ds6w:what/ds6w:topic'],
    order_by: 'desc',
    order_field: 'relevance',
    select_snippets: [
      'ds6w:snippet',
      'ds6w:label:snippet',
      'ds6w:responsible:snippet',
      'ds6w:community:snippet',
      'swym:message_text:snippet',
    ],
    nresults: PAGE_SIZE,
    source: ['3dspace'],
    tenant: getTenant(FALLBACK_TENANT),
    login: {
      '3dspace': { SecurityContext: securityContext },
    },
  }
}

function normaliseResult(raw: Record<string, unknown>): FedSearchItem {
  const attrs = (raw.attributes ?? []) as RawAttribute[]
  const flat: FedSearchItem = {}

  for (const key of TOP_LEVEL_FIELDS) {
    if (raw[key] !== undefined && raw[key] !== null) {
      flat[key] = raw[key] as string
    }
  }

  for (const attr of attrs) {
    if (attr.value !== undefined && attr.value !== null) {
      flat[attr.name] = attr.value
    } else if (Array.isArray(attr.text) && attr.text.length > 0) {
      flat[attr.name] = attr.text[0]?.content ?? ''
    }
  }

  return flat
}

export function useFederatedSearch() {
  const results = ref<FedSearchItem[]>([])
  const total = ref(0)
  const loading = ref(false)
  const error = ref<string | null>(null)
  /** Fetch progress 0–100, increasing as pages arrive. */
  const progress = ref(0)

  /**
   * Fetches all Project Spaces page by page.
   *
   *   - Page 1  → `start: 0`
   *   - Page 2+ → `next_start: <token>` from the previous `response.infos.next_start`
   *
   * The server-issued cursor is what pages reliably past the backend's ~1000-result
   * ceiling. Do NOT replace it with calculated numeric offsets.
   *
   * Stops when a page is empty, the collected count reaches `infos.nmatches`,
   * a page is shorter than PAGE_SIZE, or the cursor is missing.
   */
  async function fetchProjectSpaces() {
    loading.value = true
    error.value = null
    progress.value = 0

    try {
      const secCtx = Util.getCTX()
      if (!secCtx) {
        throw new Error(
          'SecurityContext not available yet. ' +
            'Ensure initApp.userCtxCollabspaces() has completed before this composable mounts.',
        )
      }

      const allItems: FedSearchItem[] = []
      let knownTotal: number | null = null
      let nextStart: unknown = null
      let isFirstPage = true

      // eslint-disable-next-line no-constant-condition
      while (true) {
        const pagingField = isFirstPage ? { start: 0 } : { next_start: nextStart }
        isFirstPage = false

        // eslint-disable-next-line no-await-in-loop
        const response = await httpRequest({
          method: 'POST',
          url: searchEndpoint(getPlatform().searchUrl),
          headers: SEARCH_HEADERS,
          data: { ...buildPayload(secCtx), ...pagingField },
        })
        const infos = response.data?.infos

        // Surface source-level auth / permission errors
        const sourceErr = (infos?.sources ?? []).find(
          (s: Record<string, unknown>) => s.status === false && s.error,
        )
        if (sourceErr) {
          const { errorCode, errorMessage } = sourceErr.error as Record<string, string>
          throw new Error(`[${errorCode}] ${errorMessage}`)
        }

        const rawResults: unknown[] = response.data?.results ?? []
        const pageItems = rawResults.map((item) => normaliseResult(item as Record<string, unknown>))

        if (knownTotal === null && infos?.nmatches != null) {
          knownTotal = infos.nmatches as number
          total.value = knownTotal
        }

        allItems.push(...pageItems)

        if (knownTotal !== null && knownTotal > 0) {
          progress.value = Math.min(99, Math.round((allItems.length / knownTotal) * 100))
        }

        const noResults = pageItems.length === 0
        const reachedTotal = knownTotal !== null && allItems.length >= knownTotal
        const pageWasShort = pageItems.length < PAGE_SIZE
        if (noResults || reachedTotal || pageWasShort) break

        nextStart = infos?.next_start ?? null
        if (nextStart === null) {
          console.warn('[useFederatedSearch] next_start missing from response — stopping pagination.')
          break
        }
      }

      results.value = allItems
      progress.value = 100

      // If nmatches wasn't in the response, use the collected count.
      if (total.value === 0) total.value = allItems.length
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err)
      console.warn('[useFederatedSearch] Search failed:', message)
      error.value = message
    } finally {
      loading.value = false
    }
  }

  onMounted(fetchProjectSpaces)

  return { results, total, loading, error, progress, refetch: fetchProjectSpaces }
}
