<script setup lang="ts">
import { computed, inject } from 'vue'
import { usePagination } from '@/dashboard/composables/usePagination'
import { NOT_AVAILABLE, useEventStatus } from '@/dashboard/composables/useEventStatus'
import { FED_SEARCH_KEY, PROJECT_MILESTONES_KEY } from '@/dashboard/injectionKeys'
import EventDateCell from './common/EventDateCell.vue'
import PaginationBar from './common/PaginationBar.vue'
import StatusBadge from './common/StatusBadge.vue'

const ROWS_PER_PAGE = 10

const { loading: fedLoading, error: fedError } = inject(FED_SEARCH_KEY)!
const {
  projects,
  loading: milestonesLoading,
  loadedCount,
  totalCount,
} = inject(PROJECT_MILESTONES_KEY)!

const isLoading = computed(() => fedLoading.value || milestonesLoading.value)

const { columns, rows, hasGroups, headerGroups } = useEventStatus(projects)

/** Header rows: Event Status / event / Indo|Customer when grouped, otherwise two. */
const headerRows = computed(() => (hasGroups.value ? 3 : 2))
const groupedColumns = computed(() => columns.value.filter((column) => column.group))

const { currentPage, totalPages, pageItems: pagedRows } = usePagination(rows, ROWS_PER_PAGE)

const isPlaceholder = (value: string | undefined) => !value || value.trim() === NOT_AVAILABLE
</script>

<template>
  <div class="event-status-tab tab-enter">
    <div v-if="isLoading && !projects.length" class="es-banner es-loading" role="status" aria-live="polite">
      <i class="mdi mdi-loading mdi-spin" aria-hidden="true"></i>
      Loading project milestones…
    </div>

    <div v-else-if="fedError" class="es-banner es-empty" role="alert">
      <i class="mdi mdi-alert-outline" aria-hidden="true"></i>
      Live data unavailable.
    </div>

    <div v-else-if="!projects.length" class="es-banner es-empty" role="status">
      <i class="mdi mdi-information-outline" aria-hidden="true"></i>
      No matching projects found.
    </div>

    <template v-else>
      <!-- Still loading: projects appear as they arrive -->
      <div v-if="milestonesLoading" class="es-banner es-loading" role="status" aria-live="polite">
        <i class="mdi mdi-loading mdi-spin" aria-hidden="true"></i>
        Loading project details… {{ loadedCount }} / {{ totalCount }}
      </div>

      <div class="table-container">
        <table class="data-table">
          <caption class="sr-only">
            Event status by project
          </caption>
          <thead>
            <tr>
              <th :rowspan="headerRows" scope="col">#</th>
              <th :rowspan="headerRows" scope="col">Location</th>
              <th :rowspan="headerRows" scope="col">Model</th>
              <th :rowspan="headerRows" scope="col" class="col-part">Project</th>
              <th :rowspan="headerRows" scope="col" class="numeric">Vol./Day</th>
              <th :rowspan="headerRows" scope="col">PL</th>
              <th :colspan="columns.length" scope="colgroup" class="group-header">Event Status</th>
              <th :rowspan="headerRows" scope="col">Remarks</th>
              <th :rowspan="headerRows" scope="col">Current Status /<br />Bottleneck Point</th>
            </tr>
            <tr v-if="hasGroups">
              <th
                v-for="group in headerGroups"
                :key="group.key"
                :colspan="group.span"
                :rowspan="group.column ? 2 : 1"
                :scope="group.column ? 'col' : 'colgroup'"
                :class="[
                  'event-col',
                  group.column ? { 'first-event': group.column.groupStart } : 'first-event event-group',
                ]"
              >
                {{ group.label }}
              </th>
            </tr>
            <tr v-if="hasGroups">
              <th
                v-for="column in groupedColumns"
                :key="column.key"
                scope="col"
                :class="['event-subcol', { 'first-event': column.groupStart }]"
              >
                {{ column.label }}
              </th>
            </tr>
            <tr v-else>
              <th
                v-for="column in columns"
                :key="column.key"
                scope="col"
                :class="['event-col', { 'first-event': column.groupStart }]"
              >
                {{ column.label }}
              </th>
            </tr>
          </thead>
          <tbody>
            <tr v-for="row in pagedRows" :key="row.key">
              <td class="muted">{{ row.index }}</td>
              <td class="nowrap" :class="{ muted: isPlaceholder(row.location) }">{{ row.location }}</td>
              <td>
                <span v-if="!isPlaceholder(row.model)" class="badge">{{ row.model }}</span>
                <span v-else class="muted">{{ row.model }}</span>
              </td>
              <td class="col-part">
                <div class="part-name">{{ row.name }}</div>
                <div v-if="!isPlaceholder(row.customer)" class="part-customer">{{ row.customer }}</div>
              </td>
              <td class="numeric" :class="{ muted: isPlaceholder(row.volDay) }">{{ row.volDay }}</td>
              <td :class="{ muted: isPlaceholder(row.pl) }">{{ row.pl }}</td>
              <td
                v-for="column in columns"
                :key="column.key"
                :class="{
                  'first-event': column.groupStart,
                  'mp-col': column.emphasis,
                  muted: isPlaceholder(row.cells[column.key]),
                }"
              >
                <EventDateCell :text="row.cells[column.key]" />
              </td>
              <td class="remarks" :class="{ muted: isPlaceholder(row.remarks) }">
                {{ row.remarks }}
              </td>
              <td>
                <div class="status-col">
                  <StatusBadge :status="row.status" />
                  <div v-if="!isPlaceholder(row.currentStatus)" class="current-status">
                    {{ row.currentStatus }}
                  </div>
                </div>
              </td>
            </tr>
          </tbody>
        </table>
      </div>

      <PaginationBar v-model:page="currentPage" :total-pages="totalPages" />
    </template>
  </div>
</template>

