import { ref, watch, type Ref } from 'vue'
import services from '@/services'
import Util from '@/utility/util'
import { formatMonthLabel } from '@/dashboard/utils/date'
import { parseMilestoneName, type MilestoneSide } from '@/dashboard/utils/milestones'
import { classifyTask, isTrue, projectStatusFromMilestones } from '@/dashboard/utils/projectStatus'
import type { FedSearchItem } from './useFederatedSearch'
import type { Milestone, StatusKey } from '@/dashboard/types/project'

/**
 * Only projects whose name starts with this prefix (case-insensitive) are loaded and
 * shown on the dashboard. Set to '' to include all projects.
 */
const PROJECT_NAME_PREFIX = 'MUFFLER'

export interface ProjectTask {
  id?: string
  title?: string
  type?: string
  nlsType?: string
  /** API returns "TRUE" / "FALSE" strings */
  isTypeMilestone?: string | boolean
  isTypeGate?: string | boolean
  isSummaryTask?: string | boolean
  estimatedStartDate?: string
  dueDate?: string
  forecastFinishDate?: string
  forecastStartDate?: string
  percentComplete?: string | number
  status?: string
  state?: string
  sequenceOrder?: string | number
  criticalTask?: string | boolean
  /** Nested child tasks (Milestones/Gates sit inside Phase.children[]) */
  children?: ProjectTask[]
  [key: string]: unknown
}

export interface ProjectDetail {
  projectId: string
  projectLabel: string
  title?: string
  status?: string
  percentComplete?: number
  estimatedStartDate?: string
  estimatedFinishDate?: string
  /** Flat list of ALL tasks (phases + their children) */
  tasks: ProjectTask[]
  /** Only tasks where isTypeMilestone === "TRUE" */
  milestones: ProjectTask[]
  /** Only tasks where isTypeGate === "TRUE" */
  gates: ProjectTask[]
  /** Top-level tasks (usually phases), before flattening */
  phases: ProjectTask[]
  /** Status derived from the project's milestones (the API's project status is empty) */
  statusKey: StatusKey
  /** Custom project attributes (empty string when the project does not have them) */
  attributes: ProjectAttributes
}

export interface ProjectAttributes {
  location: string
  model: string
  volDay: string
  pl: string
}

// ─── helpers ────────────────────────────────────────────────────────────────

/** Recursively flattens a task tree (phases → children) into a single list. */
function flattenTasks(tasks: ProjectTask[]): ProjectTask[] {
  const flat: ProjectTask[] = []
  for (const task of tasks) {
    flat.push(task)
    if (Array.isArray(task.children) && task.children.length > 0) {
      flat.push(...flattenTasks(task.children))
    }
  }
  return flat
}

/** Timeline marker for a milestone, labelled with its event (e.g. "PP0"). */
function taskToMilestone(task: ProjectTask): Milestone {
  const dateStr = task.dueDate ?? task.forecastFinishDate ?? task.estimatedStartDate
  const date = dateStr ? new Date(dateStr) : null
  return {
    dateLabel: date ? formatMonthLabel(date) : '',
    kind: parseMilestoneName(task.title)?.event ?? '',
    status: classifyTask(task),
  }
}

/** Markers for one side's milestones (sorted by sequence) of a project. */
function markersForSide(milestones: ProjectTask[], side: MilestoneSide): Milestone[] {
  return milestones
    .filter((m) => parseMilestoneName(m.title)?.side === side)
    .map(taskToMilestone)
}

/**
 * The project-details API returns the project either directly on the root,
 * or as the first entry of a `data` / `member` array.
 */
function extractProject(data: Record<string, unknown>): Record<string, unknown> {
  if (Array.isArray(data['data']) && data['data'].length > 0) {
    return data['data'][0] as Record<string, unknown>
  }
  return data
}

function firstEntryTasks(list: unknown): ProjectTask[] | null {
  if (!Array.isArray(list)) return null
  const first = list[0] as Record<string, unknown> | undefined
  return first && Array.isArray(first['tasks']) ? (first['tasks'] as ProjectTask[]) : null
}

/** Checked in order: { data: [{ tasks }] }, { tasks }, { member: [{ tasks }] }. */
function extractTasks(data: Record<string, unknown>): ProjectTask[] {
  return (
    firstEntryTasks(data['data']) ??
    (Array.isArray(data['tasks']) ? (data['tasks'] as ProjectTask[]) : null) ??
    firstEntryTasks(data['member']) ??
    []
  )
}

function itemLabel(item: FedSearchItem | undefined, fallback = ''): string {
  return (item?.['ds6w:label'] ?? item?.['ds6w:identifier'] ?? fallback) as string
}

/**
 * Reads a project attribute by name, ignoring case ("VolDay" / "volday"),
 * as returned with `$fields=All`. Empty string when absent or empty.
 */
function readAttribute(project: Record<string, unknown>, name: string): string {
  const wanted = name.toLowerCase()
  const key = Object.keys(project).find((k) => k.toLowerCase() === wanted)
  const value = key === undefined ? undefined : project[key]
  return value === undefined || value === null ? '' : String(value).trim()
}

interface ParsedProject {
  detail: ProjectDetail
  customerMarkers: Milestone[]
  indoMarkers: Milestone[]
}

/** Turns one project-details response into dashboard data; null if the request failed. */
function parseProjectResponse(item: FedSearchItem, id: string, raw: unknown): ParsedProject | null {
  // The API layer resolves with the axios error instead of throwing.
  const response = raw as Record<string, unknown> | null
  if (!response || response['isAxiosError'] === true) return null

  const body = response['data']
  const data =
    body && typeof body === 'object' && !Array.isArray(body)
      ? (body as Record<string, unknown>)
      : {}

  const project = extractProject(data)
  const topLevelTasks = extractTasks(data)
  const allTasks = flattenTasks(topLevelTasks)
  const milestoneTasks = allTasks
    .filter((t) => isTrue(t.isTypeMilestone))
    .sort((a, b) => Number(a.sequenceOrder ?? 0) - Number(b.sequenceOrder ?? 0))

  return {
    detail: {
      projectId: id,
      projectLabel: itemLabel(item, id),
      title: project['title'] as string | undefined,
      status: project['status'] as string | undefined,
      percentComplete: parseFloat(String(project['percentComplete'] ?? '0')) || 0,
      estimatedStartDate: project['estimatedStartDate'] as string | undefined,
      estimatedFinishDate: project['estimatedFinishDate'] as string | undefined,
      tasks: allTasks,
      milestones: milestoneTasks,
      gates: allTasks.filter((t) => isTrue(t.isTypeGate)),
      phases: topLevelTasks,
      statusKey: projectStatusFromMilestones(milestoneTasks),
      attributes: {
        location: readAttribute(project, 'Location'),
        model: readAttribute(project, 'Model'),
        volDay: readAttribute(project, 'VolDay'),
        pl: readAttribute(project, 'PL'),
      },
    },
    // Gates are not plotted.
    customerMarkers: markersForSide(milestoneTasks, 'CUSTOMER'),
    indoMarkers: markersForSide(milestoneTasks, 'INDO'),
  }
}

// ─── composable ─────────────────────────────────────────────────────────────

/** Project-detail requests in flight at once (keeps the browser and server responsive). */
const MAX_PARALLEL_REQUESTS = 10

/** While loading, partial results are pushed to the tabs at most this often. */
const PUBLISH_INTERVAL_MS = 400

export function useProjectMilestones(fedResults: Ref<FedSearchItem[]>) {
  const projects = ref<ProjectDetail[]>([])
  const loading = ref(false)
  const error = ref<string | null>(null)
  /** Customer milestones per project (circle markers), in sequence order. */
  const customerMarkersByProject = ref<Record<string, Milestone[]>>({})
  /** Indo milestones per project (square markers), in sequence order. */
  const indoMarkersByProject = ref<Record<string, Milestone[]>>({})
  /** Progress while loading: projects processed so far / projects to load. */
  const loadedCount = ref(0)
  const totalCount = ref(0)

  /** Incremented per fetch, so results of an outdated fetch are ignored. */
  let currentRun = 0

  async function fetchAll(searchItems: FedSearchItem[]) {
    if (!searchItems.length) return

    const prefix = PROJECT_NAME_PREFIX.toUpperCase()
    const items = searchItems.filter((item) => itemLabel(item).toUpperCase().startsWith(prefix))
    console.info(
      `[useProjectMilestones] Keeping ${items.length} of ${searchItems.length} projects ` +
        `(name starts with "${PROJECT_NAME_PREFIX}").`,
    )

    const run = ++currentRun
    const isCurrent = () => run === currentRun

    loading.value = true
    error.value = null
    loadedCount.value = 0
    totalCount.value = items.length

    const secCtx = Util.getCTX()
    if (!secCtx) {
      error.value = 'SecurityContext not available'
      loading.value = false
      return
    }

    // Indexed by search position, so the display order matches the search results.
    const parsed: Array<ParsedProject | null> = new Array(items.length).fill(null)
    let lastPublish = 0

    const publish = () => {
      if (!isCurrent()) return
      const done = parsed.filter((p): p is ParsedProject => p !== null)
      projects.value = done.map((p) => p.detail)
      customerMarkersByProject.value = Object.fromEntries(
        done.map((p) => [p.detail.projectId, p.customerMarkers]),
      )
      indoMarkersByProject.value = Object.fromEntries(
        done.map((p) => [p.detail.projectId, p.indoMarkers]),
      )
      lastPublish = Date.now()
    }

    let nextIndex = 0
    const worker = async () => {
      while (nextIndex < items.length && isCurrent()) {
        const idx = nextIndex++
        const item = items[idx]
        const id = item['resourceid'] as string | undefined
        if (id) {
          try {
            // eslint-disable-next-line no-await-in-loop
            const raw = await services.enovia().getProjectDetails(id, secCtx)
            parsed[idx] = parseProjectResponse(item, id, raw)
          } catch (err: unknown) {
            console.warn(`[useProjectMilestones] Project ${id} failed:`, err)
          }
        }
        if (!isCurrent()) return
        loadedCount.value++
        if (Date.now() - lastPublish >= PUBLISH_INTERVAL_MS) publish()
      }
    }

    try {
      const workerCount = Math.min(MAX_PARALLEL_REQUESTS, items.length)
      await Promise.all(Array.from({ length: workerCount }, worker))
      publish()
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err)
      console.warn('[useProjectMilestones] Unexpected error:', message)
      if (isCurrent()) error.value = message
    } finally {
      if (isCurrent()) loading.value = false
    }
  }

  watch(
    fedResults,
    (items) => {
      if (items && items.length > 0) fetchAll(items)
    },
    { immediate: true },
  )

  return {
    projects,
    customerMarkersByProject,
    indoMarkersByProject,
    loading,
    loadedCount,
    totalCount,
    error,
    refetch: () => fetchAll(fedResults.value ?? []),
  }
}
