import { computed, type Ref } from 'vue'
import { STATUS_META } from '@/dashboard/constants/status'
import { formatDayLabel, parseApiDate } from '@/dashboard/utils/date'
import {
  collectMilestoneEvents,
  findMilestone,
  MILESTONE_SIDES,
  SIDE_LABELS,
  type MilestoneSide,
} from '@/dashboard/utils/milestones'
import { classifyTask, isTaskComplete } from '@/dashboard/utils/projectStatus'
import type { ProjectDetail, ProjectTask } from './useProjectMilestones'

/** Placeholder for values 3DEXPERIENCE does not provide. */
export const NOT_AVAILABLE = '-'

export interface EventColumn {
  key: string
  label: string
  /** Visually emphasised column (the final event). */
  emphasis?: boolean
  /** Event this column belongs to (e.g. "PP0"); grouped columns share a header. */
  group?: string
  /** Indo or Customer milestone shown in this column (live data only). */
  side?: MilestoneSide
  /** First column of a group, or of the event block: draws a divider on its left. */
  groupStart?: boolean
}

/** Second header row: an event group spanning its columns, or a standalone column. */
export interface EventHeaderGroup {
  key: string
  label: string
  span: number
  /** Set for a standalone (ungrouped) column, which spans both lower header rows. */
  column?: EventColumn
}

export interface EventRow {
  key: string
  index: number
  location: string
  model: string
  name: string
  customer: string
  volDay: string
  pl: string
  /** Cell text per EventColumn.key; a second line ("\n") is shown as a note. */
  cells: Record<string, string>
  remarks: string
  currentStatus: string
  /** Display status, e.g. "Delayed" */
  status: string
}

/** Not provided by 3DEXPERIENCE; always shows NOT_AVAILABLE. */
const QAV_COLUMN: EventColumn = { key: 'customerQAV', label: 'Customer QAV' }

function milestoneDate(task: ProjectTask): Date | null {
  return parseApiDate(task.dueDate ?? task.forecastFinishDate ?? task.estimatedStartDate)
}

/** "11 Aug '26" plus a note line for completed / late milestones. */
function milestoneCellText(task: ProjectTask): string {
  const date = milestoneDate(task)
  const dateText = date ? formatDayLabel(date) : NOT_AVAILABLE
  const status = classifyTask(task)

  if (isTaskComplete(task)) {
    return `${dateText}\n${status === 'on-track' ? 'Completed' : 'Completed late'}`
  }
  return status === 'delayed' ? `${dateText}\nLate` : dateText
}

const cellKey = (event: string, side: MilestoneSide) => `milestone:${event}:${side}`

/** Events across all projects (first-seen sequence order), each with Indo + Customer columns. */
function buildColumns(projects: ProjectDetail[]): EventColumn[] {
  const events = collectMilestoneEvents(projects)
  const columns: EventColumn[] = events.flatMap((event, eventIdx) =>
    MILESTONE_SIDES.map((side, sideIdx) => ({
      key: cellKey(event, side),
      label: SIDE_LABELS[side],
      group: event,
      side,
      groupStart: sideIdx === 0,
      emphasis: eventIdx === events.length - 1,
    })),
  )
  return [...columns, { ...QAV_COLUMN, groupStart: true }]
}

function buildRow(project: ProjectDetail, index: number, columns: EventColumn[]): EventRow {
  const cells: Record<string, string> = {}
  for (const column of columns) cells[column.key] = NOT_AVAILABLE

  for (const column of columns) {
    if (!column.group || !column.side) continue
    const milestone = findMilestone(project, column.group, column.side)
    if (milestone) cells[column.key] = milestoneCellText(milestone)
  }

  return {
    key: project.projectId,
    index,
    // Custom project attributes; "-" when the project does not have a value.
    location: project.attributes.location || NOT_AVAILABLE,
    model: project.attributes.model || NOT_AVAILABLE,
    name: project.projectLabel,
    customer: NOT_AVAILABLE,
    volDay: project.attributes.volDay || NOT_AVAILABLE,
    pl: project.attributes.pl || NOT_AVAILABLE,
    cells,
    remarks: NOT_AVAILABLE,
    currentStatus: NOT_AVAILABLE,
    status: STATUS_META[project.statusKey].label,
  }
}

/** Groups consecutive columns of the same event under one header cell. */
function buildHeaderGroups(columns: EventColumn[]): EventHeaderGroup[] {
  const groups: EventHeaderGroup[] = []
  for (const column of columns) {
    const last = groups[groups.length - 1]
    if (column.group && last && !last.column && last.label === column.group) {
      last.span++
    } else if (column.group) {
      groups.push({ key: `group:${column.group}`, label: column.group, span: 1 })
    } else {
      groups.push({ key: column.key, label: column.label, span: 1, column })
    }
  }
  return groups
}

/** Event Status table model: one row per project, Indo/Customer columns per event. */
export function useEventStatus(projects: Ref<ProjectDetail[]>) {
  const columns = computed(() => buildColumns(projects.value))
  const rows = computed(() =>
    projects.value.map((project, i) => buildRow(project, i + 1, columns.value)),
  )

  const hasGroups = computed(() => columns.value.some((column) => column.group))
  const headerGroups = computed(() => buildHeaderGroups(columns.value))

  return { columns, rows, hasGroups, headerGroups }
}
