import axios from "axios";

/**
 * HTTP transport for 3DEXPERIENCE calls.
 *
 * Inside 3DDashboard requests go through WAFData.authenticatedRequest (the platform's
 * authenticated, cross-domain request API; required on the 3DEXPERIENCE cloud, where the
 * browser blocks direct cross-site calls). Standalone, plain axios with cookies is used.
 *
 * Both paths resolve to `{ status, data }` and reject with an Error.
 */

const REQUEST_TIMEOUT_MS = 120000;

let wafData = null;

/** Called once at start-up when the DS/WAFData module is available. */
export function setWafData(module) {
  wafData = module;
}

export function transportName() {
  return wafData ? "WAFData" : "axios";
}

function parseBody(body) {
  if (typeof body !== "string") return body;
  try {
    return JSON.parse(body);
  } catch (err) {
    return body;
  }
}

function wafRequest({ method, url, headers, data }) {
  return new Promise((resolve, reject) => {
    wafData.authenticatedRequest(url, {
      method,
      headers,
      data: data === undefined ? undefined : JSON.stringify(data),
      type: "json",
      timeout: REQUEST_TIMEOUT_MS,
      onComplete: (body) => resolve({ status: 200, data: parseBody(body) }),
      onFailure: (error, body) => {
        const message = error?.message || (typeof error === "string" ? error : "Request failed");
        reject(Object.assign(new Error(message), { response: { data: parseBody(body) } }));
      },
      onTimeout: () => reject(new Error(`Request timed out: ${url}`)),
    });
  });
}

/**
 * @param {{ method?: string, url: string, headers?: object, data?: unknown }} request
 * @returns {Promise<{ status: number, data: any }>}
 */
export async function httpRequest({ method = "GET", url, headers = {}, data }) {
  const allHeaders = {
    "Content-Type": "application/json",
    Accept: "application/json",
    ...headers,
  };
  if (wafData) return wafRequest({ method, url, headers: allHeaders, data });

  const response = await axios({
    method,
    url,
    headers: allHeaders,
    data,
    withCredentials: true,
    timeout: REQUEST_TIMEOUT_MS,
  });
  return { status: response.status, data: response.data };
}
