<template>
  <v-app>
    <div v-if="initError" class="init-error" role="alert">
      <strong>The dashboard could not start.</strong>
      <span>{{ initError }}</span>
    </div>
    <MainLayout v-else-if="isWidgetLoaded" />
  </v-app>
</template>

<script>
import MainLayout from "@/layouts/MainLayout.vue";

export default {
  name: "App",
  components: { MainLayout },
  computed: {
    isWidgetLoaded() {
      return this.$store.getters.GET_WIDGET_LOAD;
    },
    initError() {
      return this.$store.getters.GET_INIT_ERROR;
    },
  },
};
</script>

