import { computed, ref, toValue, type MaybeRefOrGetter } from 'vue'

export function usePagination<T>(items: MaybeRefOrGetter<T[]>, itemsPerPage: number) {
  const currentPage = ref(1)

  const totalPages = computed(() => Math.ceil(toValue(items).length / itemsPerPage))

  const pageItems = computed(() => {
    const start = (currentPage.value - 1) * itemsPerPage
    return toValue(items).slice(start, start + itemsPerPage)
  })

  return { currentPage, totalPages, pageItems }
}
